{
    "name": "opencode-worktree-isolation",
    "version": "0.5.5",
    "description": "opencode plugin that eliminates path drift via tool-layer worktree interception",
    "type": "module",
    "main": "dist/index.js",
    "types": "dist/index.d.ts",
    "license": "MIT",
    "files": [
        "dist"
    ],
    "repository": {
        "type": "git",
        "url": "git+https://github.com/earneet/opencode-worktree-isolation.git"
    },
    "homepage": "https://github.com/earneet/opencode-worktree-isolation#readme",
    "bugs": {
        "url": "https://github.com/earneet/opencode-worktree-isolation/issues"
    },
    "scripts": {
        "build": "tsc",
        "prepare": "tsc",
        "typecheck": "tsc --noEmit",
        "test": "npm run build && node --test test/unit.test.js test/lifecycle.test.js"
    },
    "keywords": [
        "opencode",
        "opencode-plugin",
        "git",
        "worktree",
        "path-drift",
        "isolation"
    ],
    "dependencies": {
        "@opencode-ai/plugin": "^1.18.31",
        "@opencode/plugin": "^2.0.11"
    },
    "devDependencies": {
        "@types/node": "^26.1.2",
        "typescript": "^7.0.2"
    }
}
